// 03-01: arithmetic-comparison (50 exercises)
writeLesson("03-operators", 0, "arithmetic-comparison", [
  { id: "03-01-01", title: "Shopping bill calculate karo", starterCode: '// Ek shop mein 3 items hain: 250, 180, 320\n// Tax 18% lagao aur total return karo\nconst items = [250, 180, 320]\n// TODO: total nikalo with tax\n', solution: 'const items = [250, 180, 320]\nconst subtotal = items[0] + items[1] + items[2]\nconst tax = subtotal * 0.18\nconst total = subtotal + tax\nreturn total', tests: [{ input: [], expected: 883.2 }], hints: ["Pehle items ka sum nikalo", "Tax = subtotal * 0.18"] },
  { id: "03-01-02", title: "Discount price nikalo", starterCode: '// Original price 1500 hai, 25% discount hai\n// Final price return karo\nconst originalPrice = 1500\n// TODO: discount lagao\n', solution: 'const originalPrice = 1500\nconst discount = originalPrice * 0.25\nconst finalPrice = originalPrice - discount\nreturn finalPrice', tests: [{ input: [], expected: 1125 }], hints: ["Discount = price * percentage/100", "Final = original - discount"] },
  { id: "03-01-03", title: "Remainder se even/odd check", starterCode: '// Number diya hai, even hai ya odd ye check karo\n// true = even, false = odd\nconst num = 37\n// TODO: % operator use karo\n', solution: 'const num = 37\nreturn num % 2 === 0', tests: [{ input: [], expected: false }, { input: [42], expected: true }], hints: ["num % 2 === 0 means even", "Remainder 0 ho to even hai"] },
  { id: "03-01-04", title: "Multiplication table banao", starterCode: '// 7 ka table return karo array mein [7, 14, 21, 28, 35, 42, 49, 56, 63, 70]\nconst n = 7\n// TODO: loop ya map use karo\n', solution: 'const n = 7\nreturn Array.from({ length: 10 }, (_, i) => n * (i + 1))', tests: [{ input: [], expected: [7, 14, 21, 28, 35, 42, 49, 56, 63, 70] }], hints: ["Array.from se 10 elements banao", "n * (i + 1) se multiples milenge"] },
  { id: "03-01-05", title: "Celsius se Fahrenheit convert", starterCode: '// Temperature in Celsius: 37\n// Formula: F = (C × 9/5) + 32\nconst celsius = 37\n// TODO: Fahrenheit nikalo\n', solution: 'const celsius = 37\nconst fahrenheit = (celsius * 9 / 5) + 32\nreturn fahrenheit', tests: [{ input: [], expected: 98.6 }], hints: ["Formula: (C * 9/5) + 32", "Order of operations dhyan se lagao"] },
  { id: "03-01-06", title: "Circle area calculate karo", starterCode: '// Radius 5 hai, area = π × r²\nconst radius = 5\n// TODO: Math.PI use karo\n', solution: 'const radius = 5\nconst area = Math.PI * radius * radius\nreturn area', tests: [{ input: [], expected: 78.53981633974483 }], hints: ["Math.PI se pi milta hai", "Area = π * r * r"] },
  { id: "03-01-07", title: "Math.max se largest number", starterCode: '// 5 numbers hain, sabse bada nikalo\nconst nums = [23, 45, 12, 67, 34]\n// TODO: Math.max use karo with spread\n', solution: 'const nums = [23, 45, 12, 67, 34]\nreturn Math.max(...nums)', tests: [{ input: [], expected: 67 }], hints: ["...arr se array individual arguments mein convert hota hai", "Math.max(...nums) se max milta hai"] },
  { id: "03-01-08", title: "Math.min se smallest number", starterCode: '// 5 numbers hain, sabse chota nikalo\nconst nums = [23, 45, 12, 67, 34]\n// TODO: Math.min use karo\n', solution: 'const nums = [23, 45, 12, 67, 34]\nreturn Math.min(...nums)', tests: [{ input: [], expected: 12 }], hints: ["Math.min() minimum value deta hai", "Spread operator lagao array pe"] },
  { id: "03-01-09", title: "Absolute value nikalo", starterCode: '// Temperature difference calculate karo (positive chahiye)\nconst today = 28\nconst tomorrow = 22\n// TODO: Math.abs use karo\n', solution: 'const today = 28\nconst tomorrow = 22\nconst diff = Math.abs(today - tomorrow)\nreturn diff', tests: [{ input: [], expected: 6 }], hints: ["Math.abs() positive value deta hai", "Difference positive mein chahiye"] },
  { id: "03-01-10", title: "Power calculate karo", starterCode: '// 2 ki power 10 nikalo (1024)\nconst base = 2\nconst exponent = 10\n// TODO: Math.pow use karo\n', solution: 'const base = 2\nconst exponent = 10\nreturn Math.pow(base, exponent)', tests: [{ input: [], expected: 1024 }], hints: ["Math.pow(base, exp) se power milta hai", "2^10 = 1024"] },
  { id: "03-01-11", title: "Square root nikalo", starterCode: '// 144 ka square root nikalo\nconst num = 144\n// TODO: Math.sqrt use karo\n', solution: 'const num = 144\nreturn Math.sqrt(num)', tests: [{ input: [], expected: 12 }], hints: ["Math.sqrt() square root deta hai", "√144 = 12"] },
  { id: "03-01-12", title: "Math.ceil use karo", starterCode: '// Students ki books chahiye — partial bhi puri count karo\nconst totalItems = 23\nconst perBox = 5\n// TODO: kitne boxes chahiye (ceil use karo)\n', solution: 'const totalItems = 23\nconst perBox = 5\nconst boxes = Math.ceil(totalItems / perBox)\nreturn boxes', tests: [{ input: [], expected: 5 }], hints: ["Math.ceil() upar round karta hai", "23/5 = 4.6, ceil se 5"] },
  { id: "03-01-13", title: "Math.floor use karo", starterCode: '// Coins mein change nikalo — sirf purane coins\nconst amount = 47\nconst coinValue = 10\n// TODO: floor use karo\n', solution: 'const amount = 47\nconst coinValue = 10\nconst coins = Math.floor(amount / coinValue)\nreturn coins', tests: [{ input: [], expected: 4 }], hints: ["Math.floor() neeche round karta hai", "47/10 = 4.7, floor se 4"] },
  { id: "03-01-14", title: "Math.round se round karo", starterCode: '// Average score nikalo aur round karo\nconst scores = [85, 92, 78, 90, 88]\n// TODO: average nikalo aur round karo\n', solution: 'const scores = [85, 92, 78, 90, 88]\nconst avg = scores.reduce((a, b) => a + b, 0) / scores.length\nreturn Math.round(avg)', tests: [{ input: [], expected: 87 }], hints: ["Sum / length se average milta hai", "Math.round() nearest integer deta hai"] },
  { id: "03-01-15", title: "Random number range mein", starterCode: '// 1 se 10 ke beech random number nikalo (inclusive)\n// TODO: Math.random use karo\nconst randomNum = Math.floor(Math.random() * 10) + 1\nreturn { randomNum, isInRange: randomNum >= 1 && randomNum <= 10 }', solution: 'const randomNum = Math.floor(Math.random() * 10) + 1\nreturn { randomNum, isInRange: randomNum >= 1 && randomNum <= 10 }', tests: [{ input: [], expected: { randomNum: 1, isInRange: true } }], hints: ["Math.random() 0 se 1 ke beech deta hai", "floor + 1 se 1-10 range milegi"] },
  { id: "03-01-16", title: "Loose equality check", starterCode: '// Check karo: "5" aur 5 barabar hain ya nahi\nconst str = "5"\nconst num = 5\n// TODO: == use karo\n', solution: 'const str = "5"\nconst num = 5\nreturn str == num', tests: [{ input: [], expected: true }], hints: ["== type coercion karta hai", "String '5' number 5 mein convert hota hai"] },
  { id: "03-01-17", title: "Strict equality check", starterCode: '// Check karo: "5" aur 5 strictly barabar hain ya nahi\nconst str = "5"\nconst num = 5\n// TODO: === use karo\n', solution: 'const str = "5"\nconst num = 5\nreturn str === num', tests: [{ input: [], expected: false }], hints: ["=== bina type coercion ke compare karta hai", "String aur number same nahi hain strictly"] },
  { id: "03-01-18", title: "Not equal check", starterCode: '// Check karo: "hello" aur "world" same hain ya nahi\nconst a = "hello"\nconst b = "world"\n// TODO: !== use karo\n', solution: 'const a = "hello"\nconst b = "world"\nreturn a !== b', tests: [{ input: [], expected: true }], hints: ["!== strictly not equal check karta hai", "Different strings hain to true"] },
  { id: "03-01-19", title: "Greater than comparison", starterCode: '// Check karo: bank balance minimum se zyada hai ya nahi\nconst balance = 5000\nconst minimum = 1000\n// TODO: > operator use karo\n', solution: 'const balance = 5000\nconst minimum = 1000\nreturn balance > minimum', tests: [{ input: [], expected: true }], hints: ["> operator greater than check karta hai", "5000 > 1000 = true"] },
  { id: "03-01-20", title: "Less than comparison", starterCode: '// Check karo: age minimum age se kam hai ya nahi\nconst age = 16\nconst minimumAge = 18\n// TODO: < operator use karo\n', solution: 'const age = 16\nconst minimumAge = 18\nreturn age < minimumAge', tests: [{ input: [], expected: true }], hints: ["< operator less than check karta hai", "16 < 18 = true"] },
  { id: "03-01-21", title: "Greater or equal comparison", starterCode: '// Check karo: score passing marks ke barabar ya usse zyada hai\nconst score = 40\nconst passingMarks = 40\n// TODO: >= operator use karo\n', solution: 'const score = 40\nconst passingMarks = 40\nreturn score >= passingMarks', tests: [{ input: [], expected: true }], hints: [">= greater than or equal check karta hai", "40 >= 40 = true"] },
  { id: "03-01-22", title: "Less or equal comparison", starterCode: '// Check karo: temperature freezing point se kam ya barabar hai\nconst temp = -5\nconst freezing = 0\n// TODO: <= operator use karo\n', solution: 'const temp = -5\nconst freezing = 0\nreturn temp <= freezing', tests: [{ input: [], expected: true }], hints: ["<= less than or equal check karta hai", "-5 <= 0 = true"] },
  { id: "03-01-23", title: "Compound assignment += ", starterCode: '// Wallet mein 500 hai, 200 add karo\nlet wallet = 500\n// TODO: += use karo\n', solution: 'let wallet = 500\nwallet += 200\nreturn wallet', tests: [{ input: [], expected: 700 }], hints: ["wallet += 200 same as wallet = wallet + 200", "500 + 200 = 700"] },
  { id: "03-01-24", title: "Compound assignment -= ", starterCode: '// Fuel tank mein 50L hai, 12L use hua\nlet fuel = 50\n// TODO: -= use karo\n', solution: 'let fuel = 50\nfuel -= 12\nreturn fuel', tests: [{ input: [], expected: 38 }], hints: ["fuel -= 12 same as fuel = fuel - 12", "50 - 12 = 38"] },
  { id: "03-01-25", title: "Compound assignment *= ", starterCode: '// Price 200 hai, 3 items ka total nikalo\nlet price = 200\n// TODO: *= use karo\n', solution: 'let price = 200\nprice *= 3\nreturn price', tests: [{ input: [], expected: 600 }], hints: ["price *= 3 same as price = price * 3", "200 * 3 = 600"] },
  { id: "03-01-26", title: "Compound assignment /= ", starterCode: '// 100 candies 4 bachon mein divide karo\nlet candies = 100\n// TODO: /= use karo\n', solution: 'let candies = 100\ncandies /= 4\nreturn candies', tests: [{ input: [], expected: 25 }], hints: ["candies /= 4 same as candies = candies / 4", "100 / 4 = 25"] },
  { id: "03-01-27", title: "Compound assignment %= ", starterCode: '// 17 coins hain, box mein 5 rakh sakte ho, baaki bacho\nlet coins = 17\n// TODO: %= use karo\n', solution: 'let coins = 17\ncoins %= 5\nreturn coins', tests: [{ input: [], expected: 2 }], hints: ["coins %= 5 same as coins = coins % 5", "17 % 5 = 2"] },
  { id: "03-01-28", title: "Increment operator ++", starterCode: '// Counter hai, use 5 baar increment karo\nlet counter = 0\n// TODO: ++ use karo\n', solution: 'let counter = 0\ncounter++\ncounter++\ncounter++\ncounter++\ncounter++\nreturn counter', tests: [{ input: [], expected: 5 }], hints: ["counter++ ek baar increment karta hai", "5 baar post-increment = 5"] },
  { id: "03-01-29", title: "Decrement operator --", starterCode: '// Stock 10 items hai, 3 baar becha\nlet stock = 10\n// TODO: -- use karo\n', solution: 'let stock = 10\nstock--\nstock--\nstock--\nreturn stock', tests: [{ input: [], expected: 7 }], hints: ["stock-- ek baar decrement karta hai", "10 - 3 = 7"] },
  { id: "03-01-30", title: "Pre vs post increment", starterCode: '// Dono ka result alag hoga\nlet a = 5\nlet b = 5\nconst result1 = ++a\nconst result2 = b++\nreturn { a, b, result1, result2 }', solution: 'let a = 5\nlet b = 5\nconst result1 = ++a\nconst result2 = b++\nreturn { a, b, result1, result2 }', tests: [{ input: [], expected: { a: 6, b: 6, result1: 6, result2: 5 } }], hints: ["++a pehle increment karta hai, phir value deta hai", "b++ pehle value deta hai, phir increment hota hai"] },
  { id: "03-01-31", title: "NaN check karo", starterCode: '// Check karo result NaN hai ya nahi\nconst result = "hello" * 10\n// TODO: isNaN use karo\n', solution: 'const result = "hello" * 10\nreturn isNaN(result)', tests: [{ input: [], expected: true }], hints: ["isNaN() NaN detect karta hai", "String * number = NaN"] },
  { id: "03-01-32", title: "Number.isNaN use karo", starterCode: '// Precise NaN check karo\nconst val1 = NaN\nconst val2 = "hello"\nreturn {\n  val1IsNaN: Number.isNaN(val1),\n  val2IsNaN: Number.isNaN(val2)\n}', solution: 'const val1 = NaN\nconst val2 = "hello"\nreturn {\n  val1IsNaN: Number.isNaN(val1),\n  val2IsNaN: Number.isNaN(val2)\n}', tests: [{ input: [], expected: { val1IsNaN: true, val2IsNaN: false } }], hints: ["Number.isNaN() sirf actual NaN ko detect karta hai", "isNaN() string ko bhi NaN maanta hai"] },
  { id: "03-01-33", title: "Infinity check", starterCode: '// Check karo 1/0 kitna hota hai\nconst result = 1 / 0\nreturn {\n  value: result,\n  isInfinite: result === Infinity,\n  isFiniteCheck: isFinite(result)\n}', solution: 'const result = 1 / 0\nreturn {\n  value: result,\n  isInfinite: result === Infinity,\n  isFiniteCheck: isFinite(result)\n}', tests: [{ input: [], expected: { value: Infinity, isInfinite: true, isFiniteCheck: false } }], hints: ["1/0 = Infinity hota hai", "isFinite() false deta hai Infinity ke liye"] },
  { id: "03-01-34", title: "Number.isFinite use karo", starterCode: '// Check karo values finite hain ya nahi\nconst values = [42, Infinity, -Infinity, NaN, 0]\n// TODO: map karo isFinite se\n', solution: 'const values = [42, Infinity, -Infinity, NaN, 0]\nreturn values.map(v => Number.isFinite(v))', tests: [{ input: [], expected: [true, false, false, false, true] }], hints: ["Number.isFinite() sirf finite numbers ke liye true deta hai", "NaN, Infinity, -Infinity ke liye false"] },
  { id: "03-01-35", title: "Number.isInteger use karo", starterCode: '// Check karo kaunse integers hain\nconst values = [42, 3.14, -7, 0, "10", NaN]\n// TODO: map karo isInteger se\n', solution: 'const values = [42, 3.14, -7, 0, "10", NaN]\nreturn values.map(v => Number.isInteger(v))', tests: [{ input: [], expected: [true, false, true, true, false, false] }], hints: ["Number.isInteger() sirf pure integers ke liye true", "String '10' integer nahi hai"] },
  { id: "03-01-36", title: "parseInt use karo", starterCode: '// String se number nikalo\nconst price = "₹199.99"\nconst phone = "9876543210"\nreturn {\n  priceNum: parseInt(price.replace("₹", "")),\n  phoneNum: parseInt(phone)\n}', solution: 'const price = "₹199.99"\nconst phone = "9876543210"\nreturn {\n  priceNum: parseInt(price.replace("₹", "")),\n  phoneNum: parseInt(phone)\n}', tests: [{ input: [], expected: { priceNum: 199, phoneNum: 9876543210 } }], hints: ["parseInt sirf integer part nikalta hai", "NaN return hota hai agar valid number na ho"] },
  { id: "03-01-37", title: "parseFloat use karo", starterCode: '// Decimal number nikalo string se\nconst measurement = "12.5cm"\nconst price = "$99.95"\nreturn {\n  cm: parseFloat(measurement),\n  dollars: parseFloat(price)\n}', solution: 'const measurement = "12.5cm"\nconst price = "$99.95"\nreturn {\n  cm: parseFloat(measurement),\n  dollars: parseFloat(price)\n}', tests: [{ input: [], expected: { cm: 12.5, dollars: 99.95 } }], hints: ["parseFloat decimal tak number nikalta hai", "Non-numeric characters ignore hote hain"] },
  { id: "03-01-38", title: "toFixed se decimal format", starterCode: '// Price ko 2 decimal places mein format karo\nconst price = 199.9\nconst tax = 35.982\n// TODO: toFixed use karo\n', solution: 'const price = 199.9\nconst tax = 35.982\nreturn {\n  formattedPrice: price.toFixed(2),\n  formattedTax: tax.toFixed(2)\n}', tests: [{ input: [], expected: { formattedPrice: "199.90", formattedTax: "35.98" } }], hints: ["toFixed(n) n decimal places deta hai", "String return hota hai, number nahi"] },
  { id: "03-01-39", title: "toPrecision se format", starterCode: '// Number ko 3 significant digits mein format karo\nconst num = 3.14159\nconst big = 12345\n// TODO: toPrecision use karo\n', solution: 'const num = 3.14159\nconst big = 12345\nreturn {\n  precise: num.toPrecision(3),\n  bigPrecise: big.toPrecision(3)\n}', tests: [{ input: [], expected: { precise: "3.14", bigPrecise: "1.23e+4" } }], hints: ["toPrecision(n) n significant digits deta hai", "Scientific notation mein aa sakta hai"] },
  { id: "03-01-40", title: "toExponential use karo", starterCode: '// Number ko scientific notation mein convert karo\nconst atoms = 602200000000000000000000\nconst small = 0.00045\n// TODO: toExponential use karo\n', solution: 'const atoms = 602200000000000000000000\nconst small = 0.00045\nreturn {\n  atoms: atoms.toExponential(2),\n  small: small.toExponential(2)\n}', tests: [{ input: [], expected: { atoms: "6.02e+23", small: "4.50e-4" } }], hints: ["toExponential(n) n digits after decimal deta hai", "e+ means power of 10"] },
  { id: "03-01-41", title: "BMI calculator", starterCode: '// Weight (kg) aur height (m) diya hai\n// BMI = weight / (height * height)\nconst weight = 70\nconst height = 1.75\n// TODO: BMI nikalo aur 1 decimal place\n', solution: 'const weight = 70\nconst height = 1.75\nconst bmi = weight / (height * height)\nreturn parseFloat(bmi.toFixed(1))', tests: [{ input: [], expected: 22.9 }], hints: ["BMI formula: weight / height²", "toFixed(1) se 1 decimal place"] },
  { id: "03-01-42", title: "Leap year check", starterCode: '// Year diya hai, check karo leap year hai ya nahi\nconst year = 2024\n// TODO: divisible by 4, but not 100 unless also 400\n', solution: 'const year = 2024\nconst isLeap = (year % 4 === 0 && year % 100 !== 0) || (year % 400 === 0)\nreturn isLeap', tests: [{ input: [], expected: true }, { input: [1900], expected: false }, { input: [2000], expected: true }], hints: ["Divisible by 4 = possible leap", "100 se divisible nahi hona chahiye, 400 se ho to chalega"] },
  { id: "03-01-43", title: "Distance formula calculate karo", starterCode: '// Do points (x1,y1) aur (x2,y2) hain\n// Distance = √((x2-x1)² + (y2-y1)²)\nconst x1 = 1, y1 = 2\nconst x2 = 4, y2 = 6\n// TODO: distance nikalo\n', solution: 'const x1 = 1, y1 = 2\nconst x2 = 4, y2 = 6\nconst distance = Math.sqrt(Math.pow(x2 - x1, 2) + Math.pow(y2 - y1, 2))\nreturn distance', tests: [{ input: [], expected: 5 }], hints: ["Math.pow se squares nikalo", "Math.sqrt se root nikalo"] },
  { id: "03-01-44", title: "Simple interest calculate", starterCode: '// Principal 5000, Rate 8%, Time 3 years\n// SI = (P * R * T) / 100\nconst principal = 5000\nconst rate = 8\nconst time = 3\n// TODO: simple interest nikalo\n', solution: 'const principal = 5000\nconst rate = 8\nconst time = 3\nconst si = (principal * rate * time) / 100\nreturn si', tests: [{ input: [], expected: 1200 }], hints: ["SI = P * R * T / 100", "5000 * 8 * 3 / 100 = 1200"] },
  { id: "03-01-45", title: "Compound interest calculate", starterCode: '// Principal 5000, Rate 10%, Time 2 years, compounding yearly\n// A = P(1 + R/100)^T\nconst principal = 5000\nconst rate = 10\nconst time = 2\n// TODO: compound interest nikalo\n', solution: 'const principal = 5000\nconst rate = 10\nconst time = 2\nconst amount = principal * Math.pow(1 + rate / 100, time)\nconst ci = amount - principal\nreturn ci', tests: [{ input: [], expected: 1050 }], hints: ["A = P(1 + R/100)^T", "CI = Amount - Principal"] },
  { id: "03-01-46", title: "Quotient and remainder", starterCode: '// 567 ko 7 se divide karo — quotient aur remainder nikalo\nconst dividend = 567\nconst divisor = 7\n// TODO: dono nikalo\n', solution: 'const dividend = 567\nconst divisor = 7\nreturn {\n  quotient: Math.floor(dividend / divisor),\n  remainder: dividend % divisor\n}', tests: [{ input: [], expected: { quotient: 81, remainder: 0 } }], hints: ["floor se quotient milta hai", "% se remainder milta hai"] },
  { id: "03-01-47", title: "Percentage calculate karo", starterCode: '// Exam mein 350 marks aaye hain total 500 mein\n// Percentage aur grade nikalo\nconst obtained = 350\nconst total = 500\n// TODO: percentage nikalo\n', solution: 'const obtained = 350\nconst total = 500\nconst percentage = (obtained / total) * 100\nreturn percentage', tests: [{ input: [], expected: 70 }], hints: ["Percentage = (obtained / total) * 100", "350/500 * 100 = 70"] },
  { id: "03-01-48", title: "Swap without temp variable", starterCode: '// Do numbers swap karo bina temp ke\nlet a = 10\nlet b = 25\n// TODO: aur b ki values swap karo\n', solution: 'let a = 10\nlet b = 25\na = a + b\nb = a - b\na = a - b\nreturn { a, b }', tests: [{ input: [], expected: { a: 25, b: 10 } }], hints: ["a = a + b se sum store hota hai", "b = a - b se original a milta hai"] },
  { id: "03-01-49", title: "Number digit sum nikalo", starterCode: '// 1234 ke digits ka sum nikalo (1+2+3+4 = 10)\nconst num = 1234\n// TODO: sum of digits\n', solution: 'const num = 1234\nconst sum = String(num).split("").reduce((acc, d) => acc + Number(d), 0)\nreturn sum', tests: [{ input: [], expected: 10 }], hints: ["String mein convert karke split karo", "Har digit ko Number mein convert karo"] },
  { id: "03-01-50", title: "Temperature range check", starterCode: '// Temperature hai, check karo kaunse category mein aata hai\n// < 0: "Freezing", 0-15: "Cold", 16-25: "Pleasant", 26-35: "Warm", > 35: "Hot"\nconst temp = 28\n// TODO: category return karo\n', solution: 'const temp = 28\nreturn temp < 0 ? "Freezing" : temp <= 15 ? "Cold" : temp <= 25 ? "Pleasant" : temp <= 35 ? "Warm" : "Hot"', tests: [{ input: [], expected: "Warm" }, { input: [5], expected: "Cold" }, { input: [-10], expected: "Freezing" }], hints: ["Nested ternary operators use karo", "Order matters — pehle < 0 check karo"] },
])

